  if (o.skates === false) return P;
  const ks = o.ks == null ? 1 : o.ks;
  for (const sk of [PLT_GEO.skate, PLT_GEO.skate.map(([x, z]) => [x, -z])]) plt_fill(() => plt_path(P, sk), PLT_COL.skate(), inkA(0.35), 1.2, a * ks);
  plt_fill(() => { plt_stad(P, Wn.c, Wn.hw + 3, Wn.hl + 3); plt_stad(P, Wn.c, Wn.hw + 1, Wn.hl + 1, true); }, PLT_COL.skate(), null, 0, a * ks);   /* one path, even-odd: a ring */
